import type { ToggleButtonProps } from "./toggle-button.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { ToggleButtonClasses, StyledToggleButton } from "./toggle-button.styles";
import { useToggleButton } from "./hooks/use-toggle-button";

const ToggleButton = forwardRef(
  (
    {
      className,
      variant = "default",
      children,
      selected: controlledSelected,
      defaultSelected,
      onValueChange,
      disabled = false,
      size,
      required = false,
      ...props
    }: ToggleButtonProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(
      ToggleButtonClasses.root,
      {
        [ToggleButtonClasses.sm]: size === "sm",
      },
      className,
    );

    const { role, handleKeyDown, renderChildren } = useToggleButton({
      disabled,
      selected: controlledSelected,
      defaultSelected,
      onValueChange,
      children,
      variant,
      size,
      required,
    });

    return (
      <StyledToggleButton
        ref={ref}
        aria-orientation="horizontal"
        className={rootClasses}
        currentTheme={theme}
        role={role}
        variant={variant}
        onKeyDown={handleKeyDown}
        {...props}
      >
        {renderChildren()}
      </StyledToggleButton>
    );
  },
);

ToggleButton.displayName = "ToggleButton";

export default ToggleButton;
